const data = $getWorkflowStaticData('global');
const ahora = Date.now();

if (!data.d2) {
  data.d2 = {};
}

const resultados = [];

for (const item of $input.all()) {
  const tabla = item.json.tabla;
  const esquema = item.json.esquema;
  const actual = Number(item.json.registros_estimados);
  const clave = `${esquema}.${tabla}`;

  const anterior = data.d2[clave];

  let crecimiento = 0;
  let alerta = false;

  if (anterior && anterior.registros > 0) {
    const minutos =
      (ahora - anterior.fecha) / 60000;

    if (minutos >= 25 && minutos <= 35) {
      crecimiento =
        ((actual - anterior.registros) /
          anterior.registros) * 100;

      alerta = crecimiento > 20;
    }
  }

  resultados.push({
    json: {
      tabla: clave,
      registros_anteriores: anterior?.registros ?? null,
      registros_actuales: actual,
      crecimiento_porcentaje:
        Number(crecimiento.toFixed(2)),
      alerta_d2: alerta
    }
  });

  data.d2[clave] = {
    registros: actual,
    fecha: ahora
  };
}

return resultados;

